class Solution:
    def getSubarrayBeauty(self, nums: list[int], k: int, x: int) -> list[int]:
        cnt = [0] * 101
        neg = 0
        res = []
        for i, v in enumerate(nums):
            cnt[v + 50] += 1
            if v < 0: neg += 1
            if i >= k:
                old = nums[i - k]
                cnt[old + 50] -= 1
                if old < 0: neg -= 1
            if i >= k - 1:
                if neg < x:
                    res.append(0)
                else:
                    c = 0
                    for val in range(-50, 0):
                        c += cnt[val + 50]
                        if c >= x:
                            res.append(val)
                            break
        return res

