class Solution {
public:
    vector<int> getSubarrayBeauty(vector<int>& nums, int k, int x) {
        int cnt[101] = {0};
        int neg = 0;
        vector<int> res;
        for (int i = 0; i < (int)nums.size(); i++) {
            cnt[nums[i] + 50]++;
            if (nums[i] < 0) neg++;
            if (i >= k) { cnt[nums[i - k] + 50]--; if (nums[i - k] < 0) neg--; }
            if (i >= k - 1) {
                if (neg < x) res.push_back(0);
                else {
                    int c = 0, val;
                    for (val = -50; val < 0; val++) {
                        c += cnt[val + 50];
                        if (c >= x) break;
                    }
                    res.push_back(val);
                }
            }
        }
        return res;
    }
};

