class Solution {
    public int[] getSubarrayBeauty(int[] nums, int k, int x) {
        int[] cnt = new int[101];
        int neg = 0;
        int[] res = new int[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            cnt[nums[i] + 50]++;
            if (nums[i] < 0) neg++;
            if (i >= k) { cnt[nums[i - k] + 50]--; if (nums[i - k] < 0) neg--; }
            if (i >= k - 1) {
                if (neg < x) res[i - k + 1] = 0;
                else {
                    int c = 0, val = -50;
                    for (; val < 0; val++) {
                        c += cnt[val + 50];
                        if (c >= x) break;
                    }
                    res[i - k + 1] = val;
                }
            }
        }
        return res;
    }
}

