var getSubarrayBeauty = function(nums, k, x) {
    const cnt = new Array(101).fill(0);
    let neg = 0;
    const res = [];
    for (let i = 0; i < nums.length; i++) {
        cnt[nums[i] + 50]++;
        if (nums[i] < 0) neg++;
        if (i >= k) { cnt[nums[i - k] + 50]--; if (nums[i - k] < 0) neg--; }
        if (i >= k - 1) {
            if (neg < x) { res.push(0); continue; }
            let c = 0, val = -50;
            for (; val < 0; val++) {
                c += cnt[val + 50];
                if (c >= x) break;
            }
            res.push(val);
        }
    }
    return res;
};
